module sort4(input [3:0] a0,a1,a2,a3, output [3:0] s0,s1,s2,s3);
wire [3:0] a[0:3];
assign a[0]=a0; assign a[1]=a1; assign a[2]=a2; assign a[3]=a3;
// stable rank: x_ij = a_i <= a_j for i<j ; for i>j element i precedes j iff a_i < a_j
wire l01=a0<=a1, l02=a0<=a2, l03=a0<=a3, l12=a1<=a2, l13=a1<=a3, l23=a2<=a3;
// rank_i = number of elements that go before i
wire [2:0] r0 = (!l01)+(!l02)+(!l03);
wire [2:0] r1 = l01+(!l12)+(!l13);
wire [2:0] r2 = l02+l12+(!l23);
wire [2:0] r3 = l03+l13+l23;
function [3:0] pick(input [2:0] k);
 pick = (r0==k)?a0:(r1==k)?a1:(r2==k)?a2:a3;
endfunction
assign s0=pick(0), s1=pick(1), s2=pick(2), s3=pick(3);
endmodule
